//! The option sections of the manual pages, written from the
//! [table of options](crate::spec).
//!
//! Each section sits between two comment lines of reStructuredText in its
//! page, which `cargo xtask gen-docs` keeps up to date with [`update`]
//! (other generators write their sections with [`splice`]):
//!
//! ```text
//! .. BEGIN generated by `cargo xtask gen-docs`: crypttab
//!
//! **discard**, **allow-discards**
//!
//!   Pass TRIM requests through to the device (**cryptsetup
//!   --allow-discards**).
//! ...
//! .. END generated: crypttab
//! ```
//!
//! Everything outside the markers (titles, introductions, examples) is
//! written by hand.

use crate::spec::{self, Deprecation, Doc, GenerateSection, OptionSpec, Source};

/// The line that opens a section, followed by its name.
pub const BEGIN: &str = ".. BEGIN generated by `cargo xtask gen-docs`: ";

/// The line that closes a section, followed by its name.
pub const END: &str = ".. END generated: ";

/// What a section lists.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Lists {
    /// The entries of the options of a source that are not deprecated.
    Entries(Source),
    /// The deprecated options and names of a source.
    Deprecated(Source),
}

/// A generated section of a manual page.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub struct Section {
    /// The page, relative to the top of the repository.
    pub page: &'static str,
    /// The name of the section in its markers.
    pub name: &'static str,
    lists: Lists,
}

/// `zfsbootmenu(7)`.
const ZFSBOOTMENU: &str = "docs/man/zfsbootmenu.7.rst";

/// `zfsbootmenu-crypttab(5)`.
const CRYPTTAB: &str = "docs/man/zfsbootmenu-crypttab.5.rst";

/// `generate-zbm(5)`.
const GENERATE_ZBM: &str = "docs/man/generate-zbm.5.rst";

/// Every generated section.
pub static SECTIONS: &[Section] = &[
    Section {
        page: ZFSBOOTMENU,
        name: "cmdline",
        lists: Lists::Entries(Source::KernelCommandLine),
    },
    Section {
        page: ZFSBOOTMENU,
        name: "cmdline-deprecated",
        lists: Lists::Deprecated(Source::KernelCommandLine),
    },
    Section {
        page: ZFSBOOTMENU,
        name: "pool-properties",
        lists: Lists::Entries(Source::PoolProperty),
    },
    Section {
        page: ZFSBOOTMENU,
        name: "dataset-properties",
        lists: Lists::Entries(Source::DatasetProperty),
    },
    Section {
        page: ZFSBOOTMENU,
        name: "build",
        lists: Lists::Entries(Source::BuildOption),
    },
    Section {
        page: ZFSBOOTMENU,
        name: "build-deprecated",
        lists: Lists::Deprecated(Source::BuildOption),
    },
    Section {
        page: CRYPTTAB,
        name: "crypttab",
        lists: Lists::Entries(Source::Crypttab),
    },
    Section {
        page: GENERATE_ZBM,
        name: "global",
        lists: Lists::Entries(Source::GenerateZbm(GenerateSection::Global)),
    },
    Section {
        page: GENERATE_ZBM,
        name: "kernel",
        lists: Lists::Entries(Source::GenerateZbm(GenerateSection::Kernel)),
    },
    Section {
        page: GENERATE_ZBM,
        name: "components",
        lists: Lists::Entries(Source::GenerateZbm(GenerateSection::Components)),
    },
    Section {
        page: GENERATE_ZBM,
        name: "efi",
        lists: Lists::Entries(Source::GenerateZbm(GenerateSection::Efi)),
    },
];

/// The pages that have generated sections, each once.
pub fn pages() -> Vec<&'static str> {
    let mut pages: Vec<&str> = SECTIONS.iter().map(|section| section.page).collect();
    pages.dedup();
    pages
}

/// One entry: the heading, a blank line and the indented body.
fn entry(heading: &str, body: &str) -> String {
    let mut text = format!("{heading}\n\n");
    for line in body.trim_matches('\n').lines() {
        if !line.is_empty() {
            text.push_str("  ");
            text.push_str(line);
        }
        text.push('\n');
    }
    text
}

/// The entry of a deprecated option or name.
fn deprecated(deprecation: &Deprecation) -> String {
    entry(
        deprecation.heading,
        &format!("Deprecated; {}.", deprecation.instead),
    )
}

/// The entries of `spec` that a section listing `lists` has.
fn entries_of(spec: &OptionSpec, lists: Lists) -> Vec<String> {
    match lists {
        Lists::Entries(source) if spec.source == source && spec.deprecation.is_none() => {
            match spec.doc {
                Doc::Entry { heading, body } => vec![entry(heading, body)],
                Doc::Within(_) | Doc::NotInManual(_) => Vec::new(),
            }
        }
        Lists::Deprecated(source) if spec.source == source => spec
            .deprecation
            .iter()
            .chain(
                spec.aliases
                    .iter()
                    .filter_map(|alias| alias.deprecation.as_ref()),
            )
            .map(deprecated)
            .collect(),
        Lists::Entries(_) | Lists::Deprecated(_) => Vec::new(),
    }
}

impl Section {
    /// The text between the markers, without the blank lines next to them.
    pub fn render(&self) -> String {
        let entries: Vec<String> = spec::all()
            .flat_map(|spec| entries_of(spec, self.lists))
            .collect();
        entries.join("\n")
    }

    /// The same text as plain text ([`plain`]), as `zbm help` shows it.
    pub fn render_plain(&self) -> String {
        plain(&self.render())
    }
}

/// `rst`, reStructuredText as the generated sections write it, as plain
/// text for a terminal: without inline markup (bold, emphasis, literals,
/// escapes, and roles such as `:doc:`, which keep their title), a
/// `.. note::` said "Note:", and the lines of a `.. code-block::` kept as
/// they are, without the directive and the blank line after it.
pub fn plain(rst: &str) -> String {
    let mut lines: Vec<String> = Vec::new();
    // The indentation of the code block's directive, while in its block.
    let mut code: Option<usize> = None;
    let mut after_directive = false;
    for line in rst.lines() {
        let text = line.trim_start();
        let indent = line.len() - text.len();
        if let Some(at) = code {
            if text.is_empty() || indent > at {
                if !(after_directive && text.is_empty()) {
                    lines.push(line.to_owned());
                }
                after_directive = false;
                continue;
            }
            code = None;
        }
        if text.starts_with(".. code-block::") {
            (code, after_directive) = (Some(indent), true);
        } else if text == ".. note::" {
            lines.push(format!("{}Note:", &line[..indent]));
        } else {
            lines.push(inline(line));
        }
    }
    let mut text = lines.join("\n");
    if rst.ends_with('\n') {
        text.push('\n');
    }
    text
}

/// `line` without its inline markup: `*` and `**` go, and the backticks of
/// interpreted text; a literal (two backticks) keeps what it holds as it
/// is; a role, such as `:doc:`, keeps its title without its target (in
/// angle brackets); an escaped character stays, and an escaped blank goes.
fn inline(line: &str) -> String {
    let mut out = String::with_capacity(line.len());
    let mut chars = line.chars().peekable();
    // Where the text of the role being read starts in `out`.
    let mut role: Option<usize> = None;
    let mut literal = false;
    while let Some(c) = chars.next() {
        let is_double = c == '`' && chars.peek() == Some(&'`');
        if is_double {
            chars.next();
            literal = !literal;
            continue;
        }
        if literal {
            out.push(c);
            continue;
        }
        match c {
            '\\' => {
                if let Some(escaped) = chars.next().filter(|next| *next != ' ') {
                    out.push(escaped);
                }
            }
            '*' => {}
            '`' => {
                if let Some(start) = role.take() {
                    untarget(&mut out, start);
                } else {
                    let prefix = role_prefix(&out);
                    out.truncate(out.len() - prefix);
                    role = (prefix > 0).then_some(out.len());
                }
            }
            _ => out.push(c),
        }
    }
    out
}

/// The length of the role's name (`:doc:`) that `text` ends with, or 0.
fn role_prefix(text: &str) -> usize {
    let Some(name) = text.strip_suffix(':') else {
        return 0;
    };
    let Some(colon) = name.rfind(':') else {
        return 0;
    };
    let word = &name[colon + 1..];
    let is_name = !word.is_empty()
        && word
            .chars()
            .all(|c| c.is_ascii_lowercase() || c == '-' || c == '_');
    if is_name { word.len() + 2 } else { 0 }
}

/// Removes the target (` <target>`) that ends the role's text, from
/// `start` on in `out`, keeping its title.
fn untarget(out: &mut String, start: usize) {
    if !out.ends_with('>') {
        return;
    }
    if let Some(open) = out[start..].rfind(" <") {
        out.truncate(start + open);
    }
}

/// Why a page could not be updated.
#[derive(Clone, Debug, Eq, PartialEq, thiserror::Error)]
pub enum DocsError {
    /// A section of the page has no opening marker.
    #[error("{page}: no line `{BEGIN}{name}`")]
    NoBegin {
        /// The page.
        page: String,
        /// The section.
        name: String,
    },
    /// A section is opened but never closed.
    #[error("{page}: no line `{END}{name}` after its opening line")]
    NoEnd {
        /// The page.
        page: String,
        /// The section.
        name: String,
    },
    /// A marker of a section is on more than one line: only one of its
    /// copies would be written.
    #[error("{page}: a marker of `{name}` is on more than one line")]
    Twice {
        /// The page.
        page: String,
        /// The section.
        name: String,
    },
}

/// The text of `page` with its generated sections written from the table.
///
/// # Errors
///
/// [`DocsError`] when a section of the page lacks one of its markers, or
/// has one twice.
pub fn update(page: &str, text: &str) -> Result<String, DocsError> {
    SECTIONS
        .iter()
        .filter(|section| section.page == page)
        .try_fold(text.to_owned(), |text, section| {
            splice(page, &text, section.name, &section.render())
        })
}

/// The text of `page` with `body` between the markers of the section
/// `name`, a blank line on each side: the generated part of a section,
/// whoever writes it.
///
/// # Errors
///
/// [`DocsError`] when the page lacks one of the section's markers, or has
/// one twice.
pub fn splice(page: &str, text: &str, name: &str, body: &str) -> Result<String, DocsError> {
    let error = |make: fn(String, String) -> DocsError| make(page.to_owned(), name.to_owned());
    let mut lines: Vec<&str> = text.split('\n').collect();
    let begin = format!("{BEGIN}{name}");
    let end = format!("{END}{name}");
    let count = |marker: &str| lines.iter().filter(|line| **line == marker).count();
    if count(&begin) > 1 || count(&end) > 1 {
        return Err(error(|page, name| DocsError::Twice { page, name }));
    }
    let start = lines
        .iter()
        .position(|line| *line == begin)
        .ok_or_else(|| error(|page, name| DocsError::NoBegin { page, name }))?;
    let stop = lines
        .iter()
        .skip(start)
        .position(|line| *line == end)
        .map(|offset| start + offset)
        .ok_or_else(|| error(|page, name| DocsError::NoEnd { page, name }))?;
    let mut generated = vec![""];
    generated.extend(body.lines());
    generated.push("");
    lines.splice(start + 1..stop, generated);
    Ok(lines.join("\n"))
}

